    const label=document.createElement('button');label.className='table-number';label.dataset.stone=stone.id;label.dataset.worldX=layout.x.toFixed(4);label.dataset.worldZ=layout.z.toFixed(4);label.onmouseenter=()=>this.highlight(stone.id);label.onmouseleave=()=>this.highlight(null);label.onfocus=()=>this.highlight(stone.id);let press=null;label.onpointerdown=e=>{if(e.pointerType==='mouse'&&e.button!==0)return;press={x:e.clientX,y:e.clientY};label.setPointerCapture(e.pointerId);};label.onpointerup=e=>{const start=press;press=null;if(start&&Math.hypot(e.clientX-start.x,e.clientY-start.y)<8)this.onSelect(stone.id);};label.onpointercancel=()=>press=null;label.onclick=e=>{if(e.detail===0)this.onSelect(stone.id)};this.labels.append(label);const item={group,marker,label,layout};this.roots.set(stone.id,item);this.loadPairedExterior(stone,item,round);
